```javascript
import { useState, useEffect } from 'react';

export default function Clock({ time }) {
  return (
    <>  
      <h1>{time}</h1>
      <input />
    </>
  );
}

function App() {
  const [time, setTime] = useState(() => new Date());

  useEffect(() => {
    const id = setInterval(() => {
      setTime(new Date());
    }, 1000);
    return () => clearInterval(id);
  }, []);

  return <Clock time={time.toLocaleTimeString()} />;
}
